+        <div class="col-md-3 text-center mb-3">
+            <div class="mb-2">
+                @if (!string.IsNullOrWhiteSpace(avatarUrl))
+                {
+                    <img src="@avatarUrl" alt="Avatar"
+                         class="rounded-circle border"
+                         style="width: 100px; height: 100px; object-fit: cover;" />
+                }
+                else
+                {
+                    <div class="rounded-circle bg-secondary d-inline-flex align-items-center justify-content-center"
+                         style="width: 100px; height: 100px;">
+                        <span class="text-white fs-1">👤</span>
+                    </div>
+                }
+            </div>
+            <small class="text-muted text-break d-block">@avatarUrl</small>
+        </div>
+
+        <div class="col-md-9">
+            <div class="mb-3">
+                <label class="form-label">Display Name</label>
+                <input type="text" class="form-control" @bind="displayName" />
+            </div>
+            <div class="mb-3">
+                <label class="form-label">Email</label>
+                <input type="email" class="form-control" @bind="email" />
+            </div>
+            <div class="mb-3">
+                <label class="form-label">Avatar URL</label>
+                <input type="url" class="form-control" @bind="avatarUrl" />
+            </div>
+            <div class="mb-3">
+                <label class="form-label">Bio</label>
+                <textarea class="form-control" rows="3" @bind="bio"></textarea>
+            </div>
+            <div class="d-flex gap-2">
+                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
+                    @if (saving)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1"></span>
+                    }
+                    Save Changes
+                </button>
+                <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private bool loading = true;
+    private bool saving;
+    private string? successMessage;
+
+    private string displayName = "";
+    private string email = "";
+    private string avatarUrl = "";
+    private string bio = "";
+
+    private UserProfile? savedProfile;
+
+    protected override async Task OnInitializedAsync()
+    {
+        savedProfile = await SettingsService.GetProfileAsync();
+        ApplyProfile(savedProfile);
+        loading = false;
+    }
+
+    private void ApplyProfile(UserProfile profile)
+    {
+        displayName = profile.DisplayName;
+        email = profile.Email;
+        avatarUrl = profile.AvatarUrl;
+        bio = profile.Bio;
+    }
+
+    private async Task SaveAsync()
+    {
+        saving = true;
+        var updated = new UserProfile(displayName, email, avatarUrl, bio);
+        await SettingsService.SaveProfileAsync(updated);
+        savedProfile = updated;
+        successMessage = "Profile saved successfully!";
+        saving = false;
+    }
+
+    private void Discard()
+    {
+        if (savedProfile is not null)
+        {
+            ApplyProfile(savedProfile);
+        }
+        successMessage = null;
+    }
+}
+

