toolArgs.file_text:
@inject ISettingsService SettingsService

@if (loading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status"><span class="visually-hidden">Loading…</span></div>
    </div>
}
else
{
    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel />

    <div class="card mb-4">
        <div class="card-body">
            <h6 class="card-title">Two-Factor Authentication</h6>
            <div class="d-flex align-items-center gap-3 mt-2">
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@twoFactorEnabled" disabled />
                    <label class="form-check-label" for="twoFactor">
                        @(twoFactorEnabled ? "Enabled" : "Disabled")
                    </label>
                </div>
                <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                    @(twoFactorEnabled ? "● Active" : "● Inactive")
                </span>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <small class="text-muted mt-2 d-block">
                    Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </small>
            }
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h6 class="card-title mb-3">Active Sessions</h6>
            @if (sessions.Count == 0)
            {
                <p class="text-muted mb-0">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-hover align-middle mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th class="text-end"></th>
                            </tr>
                        </thead>
                        <tbody>
                            @for (var i = 0; i < sessions.Count; i++)
                            {
                                var session = sessions[i];
                                var isCurrent = i == 0;
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td class="text-end">
                                        @if (isCurrent)
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </div>
    </div>

    @if (sessionToRevoke is not null)
    {
        <div class="modal-backdrop fade show"></div>
        <div class="modal d-block fade show" tabindex="-1" role="dialog">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Revoke Session</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>
                            Are you sure you want to revoke the session on
                            <strong>@sessionToRevoke.Device</strong> from
                            <strong>@sessionToRevoke.Location</strong>?
                        </p>
                    </div>
                    <div class="modal-footer">
                        <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button type="button" class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@revoking">
                            @if (revoking)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Revoke
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
}

@code {
    private bool loading = true;
    private bool revoking;

    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();
    private ActiveSession? sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = new List<ActiveSession>(settings.Sessions);
        loading = false;
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        revoking = true;
        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        sessions.Remove(sessionToRevoke);
        sessionToRevoke = null;
        revoking = false;
    }
}

@inject ISettingsService SettingsService

@if (loading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status"><span class="visually-hidden">Loading…</span></div>
    </div>
}
else
{
    <h4 class="mb-4">Appearance Settings</h4>

    @if (message is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @message
            <button type="button" class="btn-close" @onclick="() => message = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title mb-3">Theme</h6>
                    @foreach (var t in Themes)
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{t}")" value="@t"
                                   checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title mb-3">Font Size</h6>
                    @foreach (var fs in FontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{fs}")" value="@fs"
                                   checked="@(fontSize == fs)"
                                   @onchange="() => fontSize = fs" />
                            <label class="form-check-label" for="@($"fs-{fs}")">@fs</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title mb-3">Language</h6>
                    <select class="form-select" @bind="language">
                        @foreach (var lang in Languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <div class="col-md-5">
            <div class="card sticky-top" style="top: 1rem;">
                <div class="card-header">
                    <h6 class="mb-0">Live Preview</h6>
                </div>
                <div class="card-body" style="@PreviewContainerStyle()">
                    <h5 style="@PreviewFontStyle()">Sample Heading</h5>
                    <p style="@PreviewFontStyle()" class="@(compactMode ? "mb-1" : "mb-3")">
                        This is a preview of how your content will look with the selected appearance settings.
                    </p>
                    <div class="d-flex gap-2 @(compactMode ? "mb-1" : "mb-3")">
                        <span class="badge bg-primary">Tag One</span>
                        <span class="badge bg-secondary">Tag Two</span>
                    </div>
                    <button class="btn btn-sm btn-primary" type="button">Sample Button</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private bool loading = true;
    private bool saving;
    private string? message;

    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;

    private static readonly string[] Themes = ["Light", "Dark", "System"];
    private static readonly string[] FontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
        loading = false;
    }

    private string PreviewContainerStyle()
    {
        var bg = theme switch
        {
            "Dark" => "background-color: #1a1a2e; color: #e0e0e0;",
            "System" => "background-color: #f0f0f0; color: #333;",
            _ => "background-color: #ffffff; color: #212529;"
        };
        var padding = compactMode ? "padding: 0.5rem;" : "padding: 1rem;";
        return $"{bg} {padding} border-radius: 0.375rem; transition: all 0.3s ease;";
    }

    private string PreviewFontStyle() => fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        saving = true;
        var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        message = "Appearance settings saved!";
        saving = false;
    }
}

@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="d-flex gap-4" style="min-height: 600px;">
    <SettingsSidebar ActiveSection="@activeSection"
                     OnSectionChanged="@(section => activeSection = section)" />

    <div class="flex-grow-1">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
}

